const normalized = $('WF-DPV.01 - SET | Normalizar Payload').item.json;
const dbResult = $json;
return [{
  json: {
    phone:        normalized.phone        || '',
    messageType:  normalized.messageType  || '',
    caption:      normalized.caption      || '',
    instanceName: normalized.instanceName || '',
    messageId:    normalized.messageId    || '',
    imageUrl:     normalized.imageUrl     || '',
    imageBase64:  normalized.imageBase64  || '',
    from_me:      normalized.from_me      ?? false,
    id:           dbResult.id             || null
  }
}];

const items = $input.all();
if (items.length === 0 || !items[0].json.id) {
  return [{ json: { id: null } }];
}
return items;

